#!/bin/bash
set -eu
sudo python3 -I -S -B - <<'READ_POLISH_CAPTURE'
import base64,hashlib,json,os,re,resource,socket,sys,zlib
try:
 sys.dont_write_bytecode=True;os.umask(0o077);resource.setrlimit(resource.RLIMIT_CORE,(0,0))
 if os.geteuid()!=0 or socket.gethostname()!='iZj6c4cj7edgnhdimts4l7Z':raise RuntimeError('EXACT_ROOT_SERVER_REQUIRED')
 body=zlib.decompress(base64.b64decode('',validate=True))
 if len(body)!=9189 or hashlib.sha256(body).hexdigest()!='6e12f110a6cf02172e41cdb91305fb2dc2c5b80fb4e64b545ccf7829556d0814':raise RuntimeError('EXACT_READONLY_PREFLIGHT_BYTES_REQUIRED')
 namespace={'__name__':'reviewed_read_polish_capture','__file__':'<reviewed-read-polish-capture>'}
 exec(compile(body,namespace['__file__'],'exec'),namespace);print(json.dumps(namespace['capture'](),sort_keys=True))
except BaseException as error:
 value=str(error);code=value if re.fullmatch('[A-Z][A-Z0-9_]{0,95}',value) else 'META_OPERATIONS_READ_POLISH_PREFLIGHT_REJECTED'
 print(json.dumps({'stage':'META_OPERATIONS_READ_POLISH_PREFLIGHT_REJECTED','code':code}));sys.exit(1)
READ_POLISH_CAPTURE
